&lt;li style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif; font-size: 10pt;&quot;&gt;Internet Connectivity - Min Speeds: 3.8Mbps/3.0Mbps (up/down): Latency &amp;lt;60 ms.&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:220,&amp;quot;335559739&amp;quot;:220}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
